41	import { captureUnexpectedError } from '@/lib/observability/sentry';
42	import { PlayerDataType } from '@/types';
43	import { AddPlayerInviteProxy } from '@/types/actions/CreatePlayer';
44	import type { SendEmailProxy } from '@/types/actions/SendEmail';
45	
46	type FinishedFilter = 'all' | 'finished' | 'active';
47	type AuthFilter = 'all' | 'invited' | 'claimed';
48	type EmailsVerifiedFilter = 'all' | 'verified' | 'unverified';
49	
50	const finishedFilterOptions = [
51	    { label: 'All', value: 'all' },
52	    { label: 'Finished', value: 'finished' },
53	    { label: 'Active', value: 'active' },
54	];
55	
