58	    { label: 'Invited', value: 'invited' },
59	    { label: 'Claimed', value: 'claimed' },
60	];
61	
62	const emailsVerifiedFilterOptions = [
63	    { label: 'All', value: 'all' },
64	    { label: 'Verified', value: 'verified' },
65	    { label: 'Unverified', value: 'unverified' },
66	];
67	
68	export interface Props {
69	    players: PlayerDataType[];
70	    userEmails?: string[];
71	    userIdByEmail?: Record<string, string>;
72	    onAddPlayerInvite: AddPlayerInviteProxy;
73	    onSendEmail: SendEmailProxy;
74	}
75	
76	/**
77	 * Admin table for managing players, invitations, and email verification.
78	 *
79	 * @param props - Component props.
80	 * @param props.players - Players to render in the table.
81	 * @param props.userEmails - Better Auth user emails to determine onboarding status.
82	 * @returns The rendered admin player list table.
83	 */
84	export const AdminPlayerList = ({
85	    players,
86	    userEmails,
87	    userIdByEmail,
88	    onAddPlayerInvite,
89	    onSendEmail,
90	}: Props) => {
91	    const router = useRouter();
92	    const userEmailSet = useMemo(
93	        () => new Set((userEmails ?? [])
94	            .map((email) => normalizeEmail(email)).filter((email) => email.length > 0)),
95	        [userEmails],
96	    );
97	    const [sortKey, setSortKey] = useState<SortKey>('id');
98	    const [sortDirection, setSortDirection] = useState<SortDirection>('asc');
99	    const [selectedIds, setSelectedIds] = useState<number[]>([]);
100	    const [filter, setFilter] = useState('');
101	    const [filterFinished, setFilterFinished] = useState<FinishedFilter>('all');
102	    const [filterAuth, setFilterAuth] = useState<AuthFilter>('all');
103	    const [filterEmailsVerified, setFilterEmailsVerified] = useState<EmailsVerifiedFilter>('all');
104	
105	    /**
106	     * Filters players by name and the active tri-state filters.
107	     *
108	     * @returns The filtered player list.
109	     */
110	    const filteredPlayers = useMemo(() => {
111	        if (!players) return [];
112	        const trimmedFilter = filter.trim().toLowerCase();
113	        return players.filter((player) => {
114	            if (trimmedFilter && !player.name?.toLowerCase().includes(trimmedFilter)) return false;
115	            if (filterFinished === 'finished' && !player.finished) return false;
